text:
{
  "$defs": {
    "DayEntry": {
      "properties": {
        "date": {
          "title": "Date",
          "type": "string"
        },
        "shifts": {
          "items": {
            "$ref": "#/$defs/ShiftEntry"
          },
          "title": "Shifts",
          "type": "array"
        }
      },
      "required": [
        "date",
        "shifts"
      ],
      "title": "DayEntry",
      "type": "object"
    },
    "Person": {
      "properties": {
        "id": {
          "title": "Id",
          "type": "string"
        },
        "profession": {
          "title": "Profession",
          "type": "string"
        },
        "employment_percent": {
          "title": "Employment Percent",
          "type": "integer"
        },
        "is_jumper": {
          "title": "Is Jumper",
          "type": "boolean"
        },
        "days": {
          "items": {
            "$ref": "#/$defs/DayEntry"
          },
          "title": "Days",
          "type": "array"
        }
      },
      "required": [
        "id",
        "profession",
        "employment_percent",
        "is_jumper",
        "days"
      ],
      "title": "Person",
      "type": "object"
    },
    "ShiftEntry": {
      "properties": {
        "icon": {
          "anyOf": [
            {
              "enum": [
                "Auszubildende Lerntandem",
                "Azu-Gespräche dives",
                "BESPRECHUNG",
                "Betriebsausflug",
                "Bürotag",
                "F-Dienst 1",
                "Ferien",
                "Freier Tag",
                "HomeOffice",
                "Interne Einblicke",
                "kIND kRANK",
                "Kranktag",
                "Kurse bezahlte Weiterb.",
                "L",
                "M-Dienst 3",
                "M-Dienst 4",
                "Mutterschutz",
                "N 1",
                "Obl. Fort-Bildung",
                "Persönliche Absenz",
                "RAI/RUG",
                "S-Dienst 1",
                "Schule",
                "Schultag",
                "Schülerbetreuung",
                "Schwangerschaftsurlaub",
                "SD",
                "TV-FAL",
                "Unbezahlter Urlaub",
                "Unbekannt",
                "Unfall",
                "Wunschfrei",
                "Zügelitag"
              ],
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Icon"
        },
        "length": {
          "$ref": "#/$defs/ShiftLength"
        },
        "planned_on_current_unit": {
          "title": "Planned On Current Unit",
          "type": "boolean"
        },
        "alternate_unit": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "title": "Alternate Unit"
        }
      },
      "required": [
        "length",
        "planned_on_current_unit"
      ],
      "title": "ShiftEntry",
      "type": "object"
    },
    "ShiftLength": {
      "enum": [
        "full",
        "half_left",
        "half_right"
      ],
      "title": "ShiftLength",
      "type": "string"
    }
  },
  "properties": {
    "year": {
      "title": "Year",
      "type": "integer"
    },
    "month": {
      "title": "Month",
      "type": "string"
    },
    "persons": {
      "items": {
        "$ref": "#/$defs/Person"
      },
      "title": "Persons",
      "type": "array"
    }
  },
  "required": [
    "year",
    "month",
    "persons"
  ],
  "title": "Schedule",
  "type": "object"
}
